'use strict';

// MODULES //

var f32 = require( '@stdlib/number/float64/base/to-float32' );
var lnf = require( '@stdlib/math/base/special/lnf' );
var polyval = require( './polyval_p.js' );


// MAIN //

/**
* Evaluates the digamma function via asymptotic expansion.
*
* @private
* @param {number} x - input value
* @returns {number} function value
*/
function digammaf( x ) {
	var xc;
	var y;
	var z;

	xc = f32( x - 1.0 );
	y = f32( lnf( xc ) + f32( 1.0 / f32( 2.0 * xc ) ) );
	z = f32( 1.0 / f32( xc * xc ) );
	return f32( y - f32( z * polyval( z ) ) );
}


// EXPORTS //

module.exports = digammaf;
